<div class="d-flex justify-content-between mb-4"><h1>Membership fee schedules</h1><a class="btn btn-primary" href="<?=e(url('/finance/fees/create'))?>">New schedule</a></div>
<?php if($create):?><form method="post" action="<?=e(url('/finance/fees'))?>" class="card card-body mb-4"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Membership type</label><select name="membership_type_id" class="form-select" required><?php foreach($types as $t):?><option value="<?=e($t['id'])?>"><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Amount</label><input name="amount" inputmode="decimal" class="form-control" required></div><div class="col-md-3"><label class="form-label">Currency</label><input name="currency" value="ZAR" maxlength="3" class="form-control" required></div><div class="col-md-4"><label class="form-label">Billing period</label><select name="billing_period" class="form-select"><option value="annual">Annual</option><option value="monthly">Monthly</option><option value="once">Once</option></select></div><div class="col-md-4"><label class="form-label">Effective from</label><input type="date" name="effective_from" class="form-control" required></div><div class="col-md-4"><label class="form-label">Effective to (optional)</label><input type="date" name="effective_to" class="form-control"></div></div><button class="btn btn-primary mt-3">Create effective schedule</button></form><?php endif;?>
<div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Type</th><th>Fee</th><th>Period</th><th>Effective</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($fees as $f):?><tr><td><?=e($f['fee_reference'])?></td><td><?=e($f['membership_type_name'])?></td><td><?=e($f['currency'].' '.$f['amount'])?></td><td><?=e($f['billing_period'])?></td><td><?=e($f['effective_from'].' — '.($f['effective_to']?:'open'))?></td><td><?= $f['active']?'Active':'Inactive'?></td><td><?php if($f['active']):?><form method="post" action="<?=e(url('/finance/fees/'.$f['fee_reference'].'/deactivate'))?>" onsubmit="return confirm('Deactivate this schedule? Historical invoices will remain unchanged.')"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger">Deactivate</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
